// Stop — nothing personal sits outside data/ when a turn ends.
//
// The guard before each edit (guard-harness-privacy.mjs) sees only the edit
// tools. A shell command, a script, or a file generated by a build writes past
// it. So the whole-tree check that `npm run check` runs (ux/scripts/
// check-privacy.mjs: her name and every name in people/ against every file
// outside the record, and every long line of the record against the same) runs
// here too, at the end of every turn. It takes about a tenth of a second.
//
// On a leak the turn does not end quietly: the check's own findings go back to
// the model, once, to move the content into data/ or rewrite it without the
// personal part. The save hook has already committed the turn; a leak found now
// is fixed in the next commit, and history still holds the leaked line, which is
// why this runs every turn rather than at some later build.
//
// Whose leak it is. Many sessions share this tree, and a leak another session
// wrote into an untracked file (its scratch script in temp/) is not this one's
// to fix: blocking here taught every session to wave the check through. So a
// finding blocks this turn when its file is tracked by git, whoever wrote it,
// or when this session touched it (lib/touched.mjs). Only an untracked file
// another session wrote is left to that session, whose own stop still reports
// it; untracked files never reach history, and the pre-commit hook checks
// every staged file regardless.
//
// ARC-004, PRD-007, SFG-004, SFG-005; policies/PRIVACY_POLICY.md.

import { readHookInput, block, pass, repoRoot, existsFile, gitOk } from '../lib/hook.mjs';
import { touchedBy, isTouched } from '../lib/touched.mjs';
import { spawnSync } from 'node:child_process';
import { join } from 'node:path';

const input = await readHookInput();
if (input?.stop_hook_active) pass();

const script = join(repoRoot, 'ux', 'scripts', 'check-privacy.mjs');
if (!existsFile(script)) pass();

// 45 s, under the 60 s a command hook is given by default. The scan takes about
// 13 s on a OneDrive-synced disk and ran past the old 20 s whenever another
// session or a build was busy, which reported a leak that was only a timeout.
// DEAR_PRIVACY_STOP_TIMEOUT_MS shortens it only for test-privacy-timeout.mjs.
const timeout = Number(process.env.DEAR_PRIVACY_STOP_TIMEOUT_MS) || 45000;
const run = spawnSync(process.execPath, [script], { cwd: join(repoRoot, 'ux'), encoding: 'utf8', timeout, windowsHide: true });
if (run.status === 0) pass();

// A scan that did not finish found nothing, and saying it did sends a session
// hunting for a leak that is not there (2026-10-05: "something personal is
// outside data/" over an ETIMEDOUT, clean by hand in 25 s). It still blocks,
// since the tree is unconfirmed, but says what actually happened.
if (run.error) {
  block(
    [
      `PRIVACY CHECK DID NOT FINISH (${run.error.message}): nothing was found, but the tree is unconfirmed.`,
      'Run it by hand from ux/: node scripts/check-privacy.mjs. If it reports clean, carry on; if it names a file, move the personal part into data/ or rewrite it without it.',
    ].join('\n'),
  );
}

// The findings go into the model's context, so they are capped: a folder of
// thousands of hits (an import's scratch copy in temp/) once returned a megabyte
// and made every turn fail with "prompt too long". The full list is one command away.
const MAX_LINES = 40;
const all = (run.stderr || run.stdout || `the check did not finish (${run.error?.message ?? 'no output'})`).trim().split('\n');

// A finding reads "  - <path> names …" or "  - <path>:<line> repeats …". Anything
// that does not parse as one stays in: when unsure, it is this session's. The line
// number is not part of the path: read as one, a copied line in a tracked file was
// taken for another session's untracked file and passed (A-155, 2026-11-01). Copies
// are named by path and line only, never the line, so nothing here echoes one.
const mine = touchedBy(input?.session_id);
const FINDING = /^\s+- (.+?)(?::\d+)? (names|repeats) /;
const othersOnly = (line) => {
  const m = FINDING.exec(line);
  if (!m) return false;
  const file = m[1];
  return !isTouched(mine, file) && !gitOk(['ls-files', '--error-unmatch', '--', file]);
};
const findings = all.filter((l) => FINDING.test(l));
if (findings.length && findings.every(othersOnly)) pass();
const lines = all.filter((l) => !othersOnly(l));
const shown = lines.slice(0, MAX_LINES);
if (lines.length > MAX_LINES) shown.push(`  … and ${lines.length - MAX_LINES} more lines. Full list: node ux/scripts/check-privacy.mjs`);

block(
  [
    'PRIVACY CHECK FAILED: something personal is outside data/. Move it into the right file under data/, or rewrite it without the personal part. Do not mention this to her. If she is in crisis or distressed, stay with her and fix this afterwards: safety comes first (policies/SAFETY_POLICY.md).',
    '',
    ...shown,
  ].join('\n'),
);
